"""
Stock Picker API — Flask backend
Scores stocks using fundamental + technical signals and returns top picks.
"""

from flask import Flask, jsonify, request
from flask_cors import CORS
import yfinance as yf
import pandas as pd
import numpy as np
from datetime import datetime, timedelta
import logging

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

app = Flask(__name__)
CORS(app)

# ── Universe of stocks to evaluate ──────────────────────────────────────────
STOCK_UNIVERSE = {
    "Technology": [
        "AAPL", "MSFT", "GOOGL", "META", "NVDA",
        "AMD", "INTC", "CRM", "ADBE", "ORCL",
        "QCOM", "TXN", "AVGO", "MU", "AMAT",
    ],
    "Healthcare": [
        "JNJ", "UNH", "LLY", "ABBV", "MRK",
        "PFE", "TMO", "ABT", "DHR", "AMGN",
    ],
    "Financials": [
        "JPM", "BAC", "WFC", "GS", "MS",
        "BLK", "AXP", "V", "MA", "SCHW",
    ],
    "Consumer": [
        "AMZN", "TSLA", "HD", "MCD", "NKE",
        "SBUX", "TGT", "COST", "WMT", "DIS",
    ],
    "Energy": [
        "XOM", "CVX", "COP", "SLB", "EOG",
    ],
    "Industrials": [
        "CAT", "HON", "UPS", "LMT", "RTX",
    ],
}

ALL_TICKERS = [t for tickers in STOCK_UNIVERSE.values() for t in tickers]


# ── Scoring helpers ──────────────────────────────────────────────────────────

def compute_rsi(prices: pd.Series, period: int = 14) -> float:
    """Return the latest RSI value."""
    delta = prices.diff()
    gain = delta.clip(lower=0)
    loss = -delta.clip(upper=0)
    avg_gain = gain.rolling(period).mean()
    avg_loss = loss.rolling(period).mean()
    rs = avg_gain / avg_loss.replace(0, np.nan)
    rsi = 100 - (100 / (1 + rs))
    return float(rsi.iloc[-1]) if not rsi.empty else 50.0


def compute_momentum_score(prices: pd.Series) -> float:
    """
    Composite momentum: 1-month, 3-month, and 6-month returns
    weighted 40 / 35 / 25 respectively.
    Returns a score in [0, 100].
    """
    if len(prices) < 130:
        return 50.0
    ret_1m = (prices.iloc[-1] / prices.iloc[-22] - 1) * 100
    ret_3m = (prices.iloc[-1] / prices.iloc[-66] - 1) * 100
    ret_6m = (prices.iloc[-1] / prices.iloc[-130] - 1) * 100
    raw = 0.40 * ret_1m + 0.35 * ret_3m + 0.25 * ret_6m
    # Clamp to a useful range and normalise to 0-100
    score = max(0.0, min(100.0, 50.0 + raw * 1.5))
    return round(score, 2)


def moving_average_signal(prices: pd.Series) -> float:
    """
    MA signal: price vs 50-day and 200-day MAs.
    Score 0-100 (higher = more bullish).
    """
    if len(prices) < 200:
        return 50.0
    price = prices.iloc[-1]
    ma50  = prices.rolling(50).mean().iloc[-1]
    ma200 = prices.rolling(200).mean().iloc[-1]
    score = 50.0
    if price > ma50:
        score += 20
    if price > ma200:
        score += 20
    if ma50 > ma200:          # golden cross territory
        score += 10
    return min(100.0, score)


def score_pe(pe: float | None) -> float:
    """Prefer moderate P/E (8-25). Returns 0-100."""
    if pe is None or pe <= 0:
        return 40.0
    if pe < 8:
        return 55.0           # possibly value trap, slight penalty
    if pe <= 15:
        return 90.0
    if pe <= 25:
        return 75.0
    if pe <= 40:
        return 55.0
    return max(0.0, 55.0 - (pe - 40) * 0.5)


def score_eps_growth(eps_growth: float | None) -> float:
    """Prefer strong EPS growth. Returns 0-100."""
    if eps_growth is None:
        return 50.0
    if eps_growth >= 30:
        return 100.0
    if eps_growth >= 15:
        return 80.0
    if eps_growth >= 5:
        return 60.0
    if eps_growth >= 0:
        return 45.0
    return max(0.0, 45.0 + eps_growth)   # penalty for negative growth


def score_debt_equity(de: float | None) -> float:
    """Prefer lower D/E ratio. Returns 0-100."""
    if de is None:
        return 50.0
    if de < 0.3:
        return 90.0
    if de < 0.8:
        return 75.0
    if de < 1.5:
        return 55.0
    if de < 3.0:
        return 40.0
    return 20.0


def score_profit_margin(margin: float | None) -> float:
    """Prefer higher profit margins. Returns 0-100."""
    if margin is None:
        return 50.0
    pct = margin * 100
    if pct >= 25:
        return 95.0
    if pct >= 15:
        return 80.0
    if pct >= 8:
        return 65.0
    if pct >= 0:
        return 45.0
    return 20.0


def score_rsi(rsi: float) -> float:
    """
    Sweet-spot RSI: ~40-65 (not overbought, not in free fall).
    Returns 0-100.
    """
    if 40 <= rsi <= 65:
        return 90.0
    if 30 <= rsi < 40:
        return 75.0           # slightly oversold — potential rebound
    if 65 < rsi <= 75:
        return 60.0
    if rsi < 30:
        return 50.0           # deeply oversold — risky
    return 30.0               # overbought (>75)


def build_rationale(info: dict, scores: dict) -> list[str]:
    """Return a list of human-readable reasons for buying this stock."""
    reasons = []
    pe = info.get("forwardPE") or info.get("trailingPE")
    margin = info.get("profitMargins")
    eps_growth = info.get("earningsGrowth")
    de = info.get("debtToEquity")

    if scores["momentum"] >= 70:
        reasons.append("📈 Strong price momentum across 1-, 3-, and 6-month periods")
    if scores["ma"] >= 80:
        reasons.append("✅ Trading above both 50-day and 200-day moving averages")
    if pe and 0 < pe <= 20:
        reasons.append(f"💰 Attractive valuation — Forward P/E of {pe:.1f}x")
    if margin and margin >= 0.15:
        reasons.append(f"🏆 High profit margin of {margin*100:.1f}%")
    if eps_growth and eps_growth >= 0.15:
        reasons.append(f"🚀 EPS growth of {eps_growth*100:.1f}% YoY")
    if de is not None and de < 0.8:
        reasons.append(f"🔒 Low debt-to-equity ratio of {de:.2f} — strong balance sheet")
    if scores["rsi_score"] >= 75:
        reasons.append("⚡ RSI in an ideal buying zone (not overbought)")
    if not reasons:
        reasons.append("📊 Well-rounded score across multiple financial metrics")
    return reasons


# ── Core fetcher / scorer ────────────────────────────────────────────────────

def fetch_and_score(ticker: str) -> dict | None:
    """Fetch data for a single ticker and return a scored dict."""
    try:
        stock = yf.Ticker(ticker)
        info  = stock.info or {}

        # Need at least a current price
        current_price = (
            info.get("currentPrice")
            or info.get("regularMarketPrice")
            or info.get("previousClose")
        )
        if not current_price:
            return None

        # Price history (1 year)
        hist = stock.history(period="1y")
        if hist.empty or len(hist) < 30:
            return None
        prices = hist["Close"]

        # ── Compute sub-scores ──
        rsi_val       = compute_rsi(prices)
        momentum      = compute_momentum_score(prices)
        ma_signal     = moving_average_signal(prices)

        pe            = info.get("forwardPE") or info.get("trailingPE")
        eps_growth    = info.get("earningsGrowth")
        debt_equity   = info.get("debtToEquity")
        profit_margin = info.get("profitMargins")

        sub_scores = {
            "momentum":  momentum,
            "ma":        ma_signal,
            "pe":        score_pe(pe),
            "eps":       score_eps_growth(eps_growth * 100 if eps_growth else None),
            "debt":      score_debt_equity(debt_equity),
            "margin":    score_profit_margin(profit_margin),
            "rsi_score": score_rsi(rsi_val),
        }

        # Weighted composite (weights sum to 1.0)
        weights = {
            "momentum":  0.20,
            "ma":        0.15,
            "pe":        0.15,
            "eps":       0.20,
            "debt":      0.10,
            "margin":    0.10,
            "rsi_score": 0.10,
        }
        composite = sum(sub_scores[k] * weights[k] for k in weights)

        # ── 52-week range ──
        week52_low  = info.get("fiftyTwoWeekLow",  current_price * 0.7)
        week52_high = info.get("fiftyTwoWeekHigh", current_price * 1.3)
        range_pct   = round(
            (current_price - week52_low) / max(week52_high - week52_low, 0.01) * 100, 1
        )

        # ── Price history for sparkline (last 90 days) ──
        spark = prices.tail(90).round(2).tolist()

        # ── Sector lookup ──
        sector = next(
            (s for s, tickers in STOCK_UNIVERSE.items() if ticker in tickers),
            info.get("sector", "Unknown"),
        )

        rationale = build_rationale(info, sub_scores)

        return {
            "ticker":         ticker,
            "name":           info.get("shortName", ticker),
            "sector":         sector,
            "score":          round(composite, 1),
            "currentPrice":   round(current_price, 2),
            "change1d":       round(info.get("regularMarketChangePercent", 0) * 100
                                    if isinstance(info.get("regularMarketChangePercent"), float)
                                    and info.get("regularMarketChangePercent", 0) < 1
                                    else info.get("regularMarketChangePercent", 0), 2),
            "week52Low":      round(week52_low, 2),
            "week52High":     round(week52_high, 2),
            "week52RangePct": range_pct,
            "marketCap":      info.get("marketCap"),
            "pe":             round(pe, 2) if pe else None,
            "eps":            round(info.get("trailingEps", 0) or 0, 2),
            "epsGrowth":      round(eps_growth * 100, 1) if eps_growth else None,
            "profitMargin":   round(profit_margin * 100, 1) if profit_margin else None,
            "debtToEquity":   round(debt_equity, 2) if debt_equity else None,
            "rsi":            round(rsi_val, 1),
            "dividendYield":  round((info.get("dividendYield") or 0) * 100, 2),
            "subScores":      {k: round(v, 1) for k, v in sub_scores.items()},
            "sparkline":      spark,
            "rationale":      rationale,
        }
    except Exception as exc:
        logger.warning("Failed to fetch %s: %s", ticker, exc)
        return None


# ── API Routes ───────────────────────────────────────────────────────────────

@app.route("/api/top-stocks")
def top_stocks():
    """Return the top N scored stocks. Query param: n (default 10), sector (optional)."""
    n            = int(request.args.get("n", 10))
    sector_filter = request.args.get("sector", "all").strip().lower()

    if sector_filter != "all":
        tickers = [
            t for s, tickers in STOCK_UNIVERSE.items()
            if s.lower() == sector_filter
            for t in tickers
        ]
        if not tickers:
            tickers = ALL_TICKERS
    else:
        tickers = ALL_TICKERS

    results = []
    for ticker in tickers:
        data = fetch_and_score(ticker)
        if data:
            results.append(data)

    results.sort(key=lambda x: x["score"], reverse=True)
    top = results[:n]

    return jsonify({
        "generated": datetime.utcnow().isoformat() + "Z",
        "count":     len(top),
        "stocks":    top,
    })


@app.route("/api/sectors")
def sectors():
    """Return available sectors."""
    return jsonify({"sectors": ["all"] + list(STOCK_UNIVERSE.keys())})


@app.route("/api/stock/<ticker>")
def single_stock(ticker: str):
    """Return detailed data for a single ticker."""
    data = fetch_and_score(ticker.upper())
    if not data:
        return jsonify({"error": f"Could not fetch data for {ticker}"}), 404
    return jsonify(data)


@app.route("/api/health")
def health():
    return jsonify({"status": "ok", "time": datetime.utcnow().isoformat() + "Z"})


if __name__ == "__main__":
    app.run(debug=True, port=5000)

