/* ── Reset & tokens ─────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:        #0d1117;
  --bg2:       #161b22;
  --bg3:       #21262d;
  --border:    #30363d;
  --text:      #e6edf3;
  --muted:     #8b949e;
  --accent:    #58a6ff;
  --green:     #3fb950;
  --red:       #f85149;
  --gold:      #d29922;
  --purple:    #a371f7;
  --orange:    #f0883e;
  --radius:    12px;
  --shadow:    0 4px 24px rgba(0,0,0,.5);
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  line-height: 1.6;
  min-height: 100vh;
}

/* ── Header ──────────────────────────────────────────────────────────────── */
header {
  background: var(--bg2);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-inner {
  max-width: 1300px;
  margin: 0 auto;
  padding: 0 24px;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.logo { display: flex; align-items: center; gap: 10px; font-size: 1.2rem; font-weight: 700; }
.logo-icon { font-size: 1.5rem; }
.logo-ai { color: var(--accent); }
.header-meta { display: flex; align-items: center; gap: 16px; }
.timestamp { color: var(--muted); font-size: .85rem; }

/* ── Buttons ─────────────────────────────────────────────────────────────── */
.btn {
  border: none;
  border-radius: 8px;
  padding: 7px 16px;
  font-size: .9rem;
  font-weight: 600;
  cursor: pointer;
  transition: opacity .15s, transform .1s;
}
.btn:hover  { opacity: .85; }
.btn:active { transform: scale(.97); }
.btn-primary { background: var(--accent); color: #0d1117; }

/* ── Hero ────────────────────────────────────────────────────────────────── */
.hero {
  text-align: center;
  padding: 56px 24px 32px;
  background: linear-gradient(180deg, #161b22 0%, #0d1117 100%);
}
.hero h1 { font-size: clamp(1.6rem, 4vw, 2.6rem); font-weight: 800; margin-bottom: 10px; }
.hero p   { color: var(--muted); font-size: 1.05rem; }

/* ── Controls bar ────────────────────────────────────────────────────────── */
.controls-bar { background: var(--bg2); border-bottom: 1px solid var(--border); }
.controls-inner {
  max-width: 1300px;
  margin: 0 auto;
  padding: 14px 24px;
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  align-items: flex-end;
}
.control-group { display: flex; flex-direction: column; gap: 4px; }
.control-group label { font-size: .78rem; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; }
.control-group select {
  background: var(--bg3);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 8px;
  padding: 6px 12px;
  font-size: .9rem;
  cursor: pointer;
}

/* ── Status banner ───────────────────────────────────────────────────────── */
.status-banner {
  max-width: 1300px;
  margin: 16px auto 0;
  padding: 10px 24px;
  border-radius: var(--radius);
  font-size: .9rem;
  font-weight: 600;
}
.status-banner.error  { background: rgba(248,81,73,.15); border: 1px solid var(--red);   color: var(--red); }
.status-banner.hidden { display: none; }

/* ── Container ───────────────────────────────────────────────────────────── */
.container { max-width: 1300px; margin: 0 auto; padding: 32px 24px 48px; }

/* ── Loading ─────────────────────────────────────────────────────────────── */
.loading-screen {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
  padding: 80px 0;
  color: var(--muted);
}
.spinner {
  width: 48px; height: 48px;
  border: 4px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin .8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* ── Cards grid ──────────────────────────────────────────────────────────── */
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 20px;
}
.hidden { display: none !important; }

/* ── Stock card ──────────────────────────────────────────────────────────── */
.card {
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  cursor: pointer;
  transition: transform .15s, box-shadow .15s, border-color .15s;
  position: relative;
  overflow: hidden;
}
.card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow);
  border-color: var(--accent);
}

/* rank badge */
.rank-badge {
  position: absolute;
  top: 14px; right: 14px;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 2px 10px;
  font-size: .78rem;
  color: var(--muted);
  font-weight: 600;
}
.rank-badge.top3 { background: rgba(212,175,55,.12); border-color: var(--gold); color: var(--gold); }

/* card header */
.card-header { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 14px; }
.ticker-circle {
  width: 48px; height: 48px;
  border-radius: 12px;
  background: var(--bg3);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .85rem;
  font-weight: 700;
  color: var(--accent);
  flex-shrink: 0;
  letter-spacing: -.02em;
}
.card-title h2 { font-size: 1rem; font-weight: 700; }
.card-title .company-name { font-size: .82rem; color: var(--muted); margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 200px; }
.sector-tag {
  display: inline-block;
  margin-top: 4px;
  font-size: .72rem;
  padding: 1px 8px;
  border-radius: 10px;
  background: var(--bg3);
  color: var(--muted);
  border: 1px solid var(--border);
}

/* score ring */
.score-block { display: flex; flex-direction: column; align-items: center; margin-left: auto; }
.score-ring {
  width: 56px; height: 56px;
  border-radius: 50%;
