/* ── StockPicker AI — frontend logic ─────────────────────────────────────── */

const API = 'http://127.0.0.1:5000/api';
let stockData = [];

// ── Boot ──────────────────────────────────────────────────────────────────
window.addEventListener('DOMContentLoaded', async () => {
  await loadSectors();
  await loadStocks();
});

// ── Sector dropdown ───────────────────────────────────────────────────────
async function loadSectors() {
  try {
    const res  = await fetch(`${API}/sectors`);
    const data = await res.json();
    const sel  = document.getElementById('sector-select');
    sel.innerHTML = '';
    data.sectors.forEach(s => {
      const opt = document.createElement('option');
      opt.value = s;
      opt.textContent = s === 'all' ? 'All Sectors' : s;
      sel.appendChild(opt);
    });
  } catch {
    /* keep default option */
  }
}

// ── Main data loader ──────────────────────────────────────────────────────
async function loadStocks() {
  const sector = document.getElementById('sector-select').value;
  const n      = document.getElementById('top-n').value;
  const url    = `${API}/top-stocks?sector=${encodeURIComponent(sector)}&n=${n}`;

  showLoading(true);
  hideBanner();

  try {
    const res  = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();

    stockData = data.stocks || [];

    const ts = data.generated
      ? 'Updated ' + new Date(data.generated).toLocaleTimeString()
      : '';
    document.getElementById('last-updated').textContent = ts;

    reRender();
  } catch (err) {
    showBanner(`⚠️ Could not reach the backend: ${err.message}. Is the Flask server running?`, 'error');
  } finally {
    showLoading(false);
  }
}

// ── Re-render cards (sort only, no new fetch) ─────────────────────────────
function reRender() {
  const sortKey = document.getElementById('sort-select').value;
  const sorted  = [...stockData].sort((a, b) => {
    if (sortKey === 'score')   return b.score   - a.score;
    if (sortKey === 'change1d') return b.change1d - a.change1d;
    if (sortKey === 'pe')      return (a.pe ?? 9999) - (b.pe ?? 9999);
    if (sortKey === 'rsi')     return a.rsi - b.rsi;
    return 0;
  });

  const grid = document.getElementById('cards-grid');
  grid.innerHTML = '';
  sorted.forEach((s, i) => grid.appendChild(buildCard(s, i + 1)));
  grid.classList.remove('hidden');

  // Draw sparklines after DOM insertion
  requestAnimationFrame(() => sorted.forEach(s => drawSparkline(s)));
}

// ── Build a stock card DOM node ───────────────────────────────────────────
function buildCard(s, rank) {
  const card = document.createElement('div');
  card.className = 'card';
  card.dataset.ticker = s.ticker;
  card.addEventListener('click', () => openModal(s));

  const scoreClass = s.score >= 72 ? 'high' : s.score >= 55 ? 'medium' : 'low';
  const chgClass   = s.change1d > 0 ? 'pos' : s.change1d < 0 ? 'neg' : 'neu';
  const chgSign    = s.change1d > 0 ? '+' : '';
  const mktCap     = formatMktCap(s.marketCap);
  const medals     = ['🥇', '🥈', '🥉'];

  card.innerHTML = `
    <span class="rank-badge ${rank <= 3 ? 'top3' : ''}">
      ${rank <= 3 ? medals[rank-1] + ' ' : ''}#${rank}
    </span>

    <div class="card-header">
      <div class="ticker-circle">${s.ticker.length > 4 ? s.ticker.slice(0,4) : s.ticker}</div>
      <div class="card-title">
        <h2>${s.ticker}</h2>
        <div class="company-name">${s.name}</div>
        <span class="sector-tag">${s.sector}</span>
      </div>
      <div class="score-block">
        <div class="score-ring ${scoreClass}">${s.score}</div>
        <div class="score-label">AI Score</div>
      </div>
    </div>

    <div class="price-row">
      <span class="price-main">$${s.currentPrice.toLocaleString()}</span>
      <span class="change-badge ${chgClass}">${chgSign}${s.change1d.toFixed(2)}%</span>
    </div>

    <div class="sparkline-wrap">
      <canvas id="spark-${s.ticker}" height="56"></canvas>
    </div>

    <div class="range-bar-wrap">
      <div class="range-bar-labels">
        <span>52W Low $${s.week52Low.toLocaleString()}</span>
        <span>52W High $${s.week52High.toLocaleString()}</span>
      </div>
      <div class="range-bar-track">
        <div class="range-bar-fill" style="width:${s.week52RangePct}%"></div>
        <div class="range-bar-dot" style="left:${s.week52RangePct}%"></div>
      </div>
    </div>

    <div class="metrics-grid">
      <div class="metric">
        <span class="metric-label">P/E</span>
        <span class="metric-value">${s.pe ?? '—'}</span>
      </div>
      <div class="metric">
        <span class="metric-label">RSI</span>
        <span class="metric-value">${s.rsi}</span>
      </div>
      <div class="metric">
        <span class="metric-label">Mkt Cap</span>
        <span class="metric-value">${mktCap}</span>
      </div>
      <div class="metric">
        <span class="metric-label">EPS Gr.</span>
        <span class="metric-value">${s.epsGrowth != null ? s.epsGrowth + '%' : '—'}</span>
      </div>
      <div class="metric">
        <span class="metric-label">Margin</span>
        <span class="metric-value">${s.profitMargin != null ? s.profitMargin + '%' : '—'}</span>
      </div>
      <div class="metric">
        <span class="metric-label">Div Yld</span>
        <span class="metric-value">${s.dividendYield > 0 ? s.dividendYield + '%' : '—'}</span>
      </div>
    </div>

    <div class="rationale">
      ${s.rationale.slice(0, 2).map(r => `<div class="rationale-item">${r}</div>`).join('')}
    </div>
  `;
  return card;
}

// ── Sparkline (pure canvas, no dependencies) ──────────────────────────────
function drawSparkline(s) {
  const canvas = document.getElementById(`spark-${s.ticker}`);
  if (!canvas || !s.sparkline || s.sparkline.length < 2) return;

  const dpr = window.devicePixelRatio || 1;
  const w   = canvas.offsetWidth;
  const h   = 56;
  canvas.width  = w * dpr;
  canvas.height = h * dpr;
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);

  const prices = s.sparkline;
  const min    = Math.min(...prices);
  const max    = Math.max(...prices);
  const range  = max - min || 1;
  const pad    = 4;

  const x = i => (i / (prices.length - 1)) * (w - pad * 2) + pad;
  const y = v => h - pad - ((v - min) / range) * (h - pad * 2);

  // gradient fill
  const grad = ctx.createLinearGradient(0, 0, 0, h);
  const isUp = prices[prices.length - 1] >= prices[0];
  const col  = isUp ? '63,185,80' : '248,81,73';
  grad.addColorStop(0,   `rgba(${col},.3)`);
  grad.addColorStop(1,   `rgba(${col},0)`);

  ctx.beginPath();
  ctx.moveTo(x(0), y(prices[0]));
  prices.forEach((p, i) => { if (i > 0) ctx.lineTo(x(i), y(p)); });
  ctx.lineTo(x(prices.length - 1), h);
  ctx.lineTo(x(0), h);
  ctx.closePath();
  ctx.fillStyle = grad;
  ctx.fill();

  // line
  ctx.beginPath();
  ctx.moveTo(x(0), y(prices[0]));
  prices.forEach((p, i) => { if (i > 0) ctx.lineTo(x(i), y(p)); });
  ctx.strokeStyle = `rgb(${col})`;
  ctx.lineWidth   = 2;
  ctx.lineJoin    = 'round';
  ctx.stroke();
}

// ── Modal ─────────────────────────────────────────────────────────────────
function openModal(s) {
  const scoreClass = s.score >= 72 ? 'high' : s.score >= 55 ? 'medium' : 'low';
  const subLabels  = { momentum: 'Momentum', ma: 'MA Signal', pe: 'Valuation', eps: 'EPS Growth', debt: 'Debt/Eq', margin: 'Margin', rsi_score: 'RSI' };

  const subBars = Object.entries(s.subScores).map(([k, v]) => `
    <div class="subscore-bar-wrap">
      <span class="subscore-label">${subLabels[k] || k}</span>
      <div class="subscore-track"><div class="subscore-fill" style="width:${v}%"></div></div>
      <span class="subscore-val">${v}</span>
    </div>`).join('');

  const rationale = s.rationale.map(r => `<div class="rationale-item">${r}</div>`).join('');

  document.getElementById('modal-content').innerHTML = `
    <div style="display:flex;align-items:center;gap:14px;margin-bottom:6px;">
      <div class="ticker-circle" style="width:52px;height:52px;font-size:1rem;">${s.ticker}</div>
      <div>
        <h2>${s.ticker} <span class="score-ring ${scoreClass}" style="display:inline-flex;width:44px;height:44px;font-size:1rem;vertical-align:middle;margin-left:8px;">${s.score}</span></h2>
        <div class="modal-sub">${s.name} &nbsp;·&nbsp; ${s.sector}</div>
      </div>
    </div>

    <div class="modal-section">
      <h4>AI Score Breakdown</h4>
      ${subBars}
    </div>

    <div class="modal-section">
      <h4>Why Buy?</h4>
      ${rationale}
    </div>

    <div class="modal-section">
      <h4>Key Metrics</h4>
      <div class="metrics-grid" style="grid-template-columns:1fr 1fr 1fr;">
        <div class="metric"><span class="metric-label">Price</span><span class="metric-value">$${s.currentPrice.toLocaleString()}</span></div>
        <div class="metric"><span class="metric-label">P/E</span><span class="metric-value">${s.pe ?? '—'}</span></div>
        <div class="metric"><span class="metric-label">RSI</span><span class="metric-value">${s.rsi}</span></div>
        <div class="metric"><span class="metric-label">EPS Gr.</span><span class="metric-value">${s.epsGrowth != null ? s.epsGrowth + '%' : '—'}</span></div>
        <div class="metric"><span class="metric-label">Margin</span><span class="metric-value">${s.profitMargin != null ? s.profitMargin + '%' : '—'}</span></div>
        <div class="metric"><span class="metric-label">D/E</span><span class="metric-value">${s.debtToEquity ?? '—'}</span></div>
        <div class="metric"><span class="metric-label">Div Yld</span><span class="metric-value">${s.dividendYield > 0 ? s.dividendYield + '%' : '—'}</span></div>
        <div class="metric"><span class="metric-label">Mkt Cap</span><span class="metric-value">${formatMktCap(s.marketCap)}</span></div>
        <div class="metric"><span class="metric-label">52W Pos</span><span class="metric-value">${s.week52RangePct}%</span></div>
      </div>
    </div>
  `;
  document.getElementById('modal-overlay').classList.remove('hidden');
}

function closeModal(evt) {
  if (evt && evt.target !== document.getElementById('modal-overlay')) return;
  document.getElementById('modal-overlay').classList.add('hidden');
}

// ── Helpers ───────────────────────────────────────────────────────────────
function formatMktCap(cap) {
  if (!cap) return '—';
  if (cap >= 1e12) return `$${(cap / 1e12).toFixed(1)}T`;
  if (cap >= 1e9)  return `$${(cap / 1e9).toFixed(1)}B`;
  if (cap >= 1e6)  return `$${(cap / 1e6).toFixed(1)}M`;
  return `$${cap}`;
}

function showLoading(on) {
  document.getElementById('loading').classList.toggle('hidden', !on);
  if (on) document.getElementById('cards-grid').classList.add('hidden');
}

function showBanner(msg, type = 'error') {
  const b = document.getElementById('status-banner');
  b.textContent = msg;
  b.className   = `status-banner ${type}`;
}

function hideBanner() {
  document.getElementById('status-banner').className = 'status-banner hidden';
}

