  1 | /* ── StockPicker AI — frontend logic ─────────────────────────────────────── */
  2 | 
  3 | const API = 'http://127.0.0.1:5000/api';
  4 | let stockData = [];
  5 | 
  6 | // ── Boot ──────────────────────────────────────────────────────────────────
  7 | window.addEventListener('DOMContentLoaded', async () => {
  8 |   await loadSectors();
  9 |   await loadStocks();
 10 | });
 11 | 
 12 | // ── Sector dropdown ───────────────────────────────────────────────────────
 13 | async function loadSectors() {
 14 |   try {
 15 |     const res  = await fetch(`${API}/sectors`);
 16 |     const data = await res.json();
 17 |     const sel  = document.getElementById('sector-select');
 18 |     sel.innerHTML = '';
 19 |     data.sectors.forEach(s => {
 20 |       const opt = document.createElement('option');
 21 |       opt.value = s;
 22 |       opt.textContent = s === 'all' ? 'All Sectors' : s;
 23 |       sel.appendChild(opt);
 24 |     });
 25 |   } catch { /* keep default */ }
 26 | }
 27 | 
 28 | // ── Main data loader ──────────────────────────────────────────────────────
 29 | async function loadStocks() {
 30 |   const sector = document.getElementById('sector-select').value;
 31 |   const n      = document.getElementById('top-n').value;
 32 |   const url    = `${API}/top-stocks?sector=${encodeURIComponent(sector)}&n=${n}`;
 33 | 
 34 |   showLoading(true);
 35 |   hideBanner();
 36 | 
 37 |   try {
 38 |     const res  = await fetch(url);
 39 |     if (!res.ok) throw new Error(`HTTP ${res.status}`);
 40 |     const data = await res.json();
 41 |     stockData  = data.stocks || [];
 42 | 
 43 |     const ts = data.generated
 44 |       ? 'Updated ' + new Date(data.generated).toLocaleTimeString()
 45 |       : '';
 46 |     document.getElementById('last-updated').textContent = ts;
 47 |     reRender();
 48 |   } catch (err) {
 49 |     showBanner(`⚠️ Could not reach the backend: ${err.message}. Is the Flask server running?`, 'error');
 50 |   } finally {
 51 |     showLoading(false);
 52 |   }
 53 | }
 54 | 
 55 | // ── Re-render (sort only) ─────────────────────────────────────────────────
 56 | function reRender() {
 57 |   const sortKey = document.getElementById('sort-select').value;
 58 |   const sorted  = [...stockData].sort((a, b) => {
 59 |     if (sortKey === 'score')    return b.score    - a.score;
 60 |     if (sortKey === 'change1d') return b.change1d - a.change1d;
 61 |     if (sortKey === 'pe')       return (a.pe ?? 9999) - (b.pe ?? 9999);
 62 |     if (sortKey === 'rsi')      return a.rsi - b.rsi;
 63 |     return 0;
 64 |   });
 65 | 
 66 |   const grid = document.getElementById('cards-grid');
 67 |   grid.innerHTML = '';
 68 |   sorted.forEach((s, i) => grid.appendChild(buildCard(s, i + 1)));
 69 |   grid.classList.remove('hidden');
 70 |   requestAnimationFrame(() => sorted.forEach(s => drawSparkline(s)));
 71 | }
 72 | 
 73 | // ── Build a stock card DOM node ───────────────────────────────────────────
 74 | function buildCard(s, rank) {
 75 |   const card = document.createElement('div');
 76 |   card.className = 'card';
 77 |   card.dataset.ticker = s.ticker;
 78 |   card.addEventListener('click', () => openModal(s));
 79 | 
 80 |   const scoreClass = s.score >= 72 ? 'high' : s.score >= 55 ? 'medium' : 'low';
 81 |   const chgClass   = s.change1d > 0 ? 'pos' : s.change1d < 0 ? 'neg' : 'neu';
 82 |   const chgSign    = s.change1d > 0 ? '+' : '';
 83 |   const mktCap     = formatMktCap(s.marketCap);
 84 |   const medals     = ['🥇','🥈','🥉'];
 85 | 
 86 |   card.innerHTML = `
 87 |     <span class="rank-badge ${rank<=3?'top3':''}">
 88 |       ${rank<=3? medals[rank-1]+' ':''}#${rank}
 89 |     </span>
 90 |     <div class="card-header">
 91 |       <div class="ticker-circle">${s.ticker.slice(0,4)}</div>
 92 |       <div class="card-title">
 93 |         <h2>${s.ticker}</h2>
 94 |         <div class="company-name">${s.name}</div>
 95 |         <span class="sector-tag">${s.sector}</span>
 96 |       </div>
 97 |       <div class="score-block">
 98 |         <div class="score-ring ${scoreClass}">${s.score}</div>
 99 |         <div class="score-label">AI Score</div>
100 |       </div>
101 |     </div>
102 |     <div class="price-row">
103 |       <span class="price-main">$${s.currentPrice.toLocaleString()}</span>
104 |       <span class="change-badge ${chgClass}">${chgSign}${s.change1d.toFixed(2)}%</span>
105 |     </div>
106 |     <div class="sparkline-wrap">
107 |       <canvas id="spark-${s.ticker}" height="56"></canvas>
108 |     </div>
109 |     <div class="range-bar-wrap">
110 |       <div class="range-bar-labels">
111 |         <span>52W Low $${s.week52Low.toLocaleString()}</span>
112 |         <span>52W High $${s.week52High.toLocaleString()}</span>
113 |       </div>
114 |       <div class="range-bar-track">
115 |         <div class="range-bar-fill" style="width:${s.week52RangePct}%"></div>
116 |         <div class="range-bar-dot" style="left:${s.week52RangePct}%"></div>
117 |       </div>
118 |     </div>
119 |     <div class="metrics-grid">
120 |       <div class="metric"><span class="metric-label">P/E</span><span class="metric-value">${s.pe??'—'}</span></div>
121 |       <div class="metric"><span class="metric-label">RSI</span><span class="metric-value">${s.rsi}</span></div>
122 |       <div class="metric"><span class="metric-label">Mkt Cap</span><span class="metric-value">${mktCap}</span></div>
123 |       <div class="metric"><span class="metric-label">EPS Gr.</span><span class="metric-value">${s.epsGrowth!=null?s.epsGrowth+'%':'—'}</span></div>
124 |       <div class="metric"><span class="metric-label">Margin</span><span class="metric-value">${s.profitMargin!=null?s.profitMargin+'%':'—'}</span></div>
125 |       <div class="metric"><span class="metric-label">Div Yld</span><span class="metric-value">${s.dividendYield>0?s.dividendYield+'%':'—'}</span></div>
126 |     </div>
127 |     <div class="rationale">
128 |       ${s.rationale.slice(0,2).map(r=>`<div class="rationale-item">${r}</div>`).join('')}
129 |     </div>`;
130 |   return card;
131 | }
132 | 
133 | // ── Sparkline (pure canvas) ───────────────────────────────────────────────
134 | function drawSparkline(s) {
135 |   const canvas = document.getElementById(`spark-${s.ticker}`);
136 |   if (!canvas || !s.sparkline || s.sparkline.length < 2) return;
137 |   const dpr = window.devicePixelRatio || 1;
138 |   const w   = canvas.offsetWidth;
139 |   const h   = 56;
140 |   canvas.width  = w * dpr;
141 |   canvas.height = h * dpr;
142 |   const ctx = canvas.getContext('2d');
143 |   ctx.scale(dpr, dpr);
144 | 
145 |   const prices = s.sparkline;
146 |   const min    = Math.min(...prices);
147 |   const max    = Math.max(...prices);
148 |   const range  = max - min || 1;
149 |   const pad    = 4;
150 |   const xFn    = i => (i / (prices.length-1)) * (w - pad*2) + pad;
151 |   const yFn    = v => h - pad - ((v - min) / range) * (h - pad*2);
152 | 
153 |   const isUp = prices[prices.length-1] >= prices[0];
154 |   const col  = isUp ? '63,185,80' : '248,81,73';
155 |   const grad = ctx.createLinearGradient(0, 0, 0, h);
156 |   grad.addColorStop(0, `rgba(${col},.3)`);
157 |   grad.addColorStop(1, `rgba(${col},0)`);
158 | 
159 |   ctx.beginPath();
160 |   ctx.moveTo(xFn(0), yFn(prices[0]));
161 |   prices.forEach((p, i) => { if (i>0) ctx.lineTo(xFn(i), yFn(p)); });
162 |   ctx.lineTo(xFn(prices.length-1), h);
163 |   ctx.lineTo(xFn(0), h);
164 |   ctx.closePath();
165 |   ctx.fillStyle = grad;
166 |   ctx.fill();
167 | 
168 |   ctx.beginPath();
169 |   ctx.moveTo(xFn(0), yFn(prices[0]));
170 |   prices.forEach((p, i) => { if (i>0) ctx.lineTo(xFn(i), yFn(p)); });
171 |   ctx.strokeStyle = `rgb(${col})`;
172 |   ctx.lineWidth   = 2;
173 |   ctx.lineJoin    = 'round';
174 |   ctx.stroke();
175 | }
176 | 
177 | // ── Modal ─────────────────────────────────────────────────────────────────
178 | function openModal(s) {
179 |   const scoreClass = s.score >= 72 ? 'high' : s.score >= 55 ? 'medium' : 'low';
180 |   const subLabels  = {
181 |     momentum: 'Momentum', ma: 'MA Signal', pe: 'Valuation',
182 |     eps: 'EPS Growth', debt: 'Debt/Eq', margin: 'Margin', rsi_score: 'RSI'
183 |   };
184 | 
185 |   const subBars = Object.entries(s.subScores).map(([k, v]) => `
186 |     <div class="subscore-bar-wrap">
187 |       <span class="subscore-label">${subLabels[k]||k}</span>
188 |       <div class="subscore-track"><div class="subscore-fill" style="width:${v}%"></div></div>
189 |       <span class="subscore-val">${v}</span>
190 |     </div>`).join('');
191 | 
192 |   const rationale = s.rationale.map(r => `<div class="rationale-item" style="margin-bottom:6px;">${r}</div>`).join('');
193 | 
194 |   document.getElementById('modal-content').innerHTML = `
195 |     <div style="display:flex;align-items:center;gap:14px;margin-bottom:16px;">
196 |       <div class="ticker-circle" style="width:52px;height:52px;font-size:1rem;">${s.ticker}</div>
197 |       <div>
198 |         <h2>${s.ticker} &nbsp;<span class="score-ring ${scoreClass}" style="display:inline-flex;width:42px;height:42px;font-size:.95rem;vertical-align:middle;">${s.score}</span></h2>
199 |         <div class="modal-sub">${s.name} &nbsp;·&nbsp; ${s.sector}</div>
200 |       </div>
201 |     </div>
202 |     <div class="modal-section">
203 |       <h4>AI Score Breakdown</h4>${subBars}
204 |     </div>
205 |     <div class="modal-section">
206 |       <h4>Why Buy?</h4>${rationale}
207 |     </div>
208 |     <div class="modal-section">
209 |       <h4>Key Metrics</h4>
210 |       <div class="metrics-grid" style="grid-template-columns:1fr 1fr 1fr;">
211 |         <div class="metric"><span class="metric-label">Price</span><span class="metric-value">$${s.currentPrice.toLocaleString()}</span></div>
212 |         <div class="metric"><span class="metric-label">P/E</span><span class="metric-value">${s.pe??'—'}</span></div>
213 |         <div class="metric"><span class="metric-label">RSI</span><span class="metric-value">${s.rsi}</span></div>
214 |         <div class="metric"><span class="metric-label">EPS Gr.</span><span class="metric-value">${s.epsGrowth!=null?s.epsGrowth+'%':'—'}</span></div>
215 |         <div class="metric"><span class="metric-label">Margin</span><span class="metric-value">${s.profitMargin!=null?s.profitMargin+'%':'—'}</span></div>
216 |         <div class="metric"><span class="metric-label">D/E</span><span class="metric-value">${s.debtToEquity??'—'}</span></div>
217 |         <div class="metric"><span class="metric-label">Div Yld</span><span class="metric-value">${s.dividendYield>0?s.dividendYield+'%':'—'}</span></div>
218 |         <div class="metric"><span class="metric-label">Mkt Cap</span><span class="metric-value">${formatMktCap(s.marketCap)}</span></div>
219 |         <div class="metric"><span class="metric-label">52W Pos</span><span class="metric-value">${s.week52RangePct}%</span></div>
220 |       </div>
221 |     </div>`;
222 |   document.getElementById('modal-overlay').classList.remove('hidden');
223 | }
224 | 
225 | function closeModal(evt) {
226 |   if (evt && evt.target !== document.getElementById('modal-overlay')) return;
227 |   document.getElementById('modal-overlay').classList.add('hidden');
228 | }
229 | 
230 | // ── Utilities ─────────────────────────────────────────────────────────────
231 | function formatMktCap(cap) {
232 |   if (!cap) return '—';
233 |   if (cap >= 1e12) return `$${(cap/1e12).toFixed(1)}T`;
234 |   if (cap >= 1e9)  return `$${(cap/1e9).toFixed(1)}B`;
235 |   if (cap >= 1e6)  return `$${(cap/1e6).toFixed(1)}M`;
236 |   return `$${cap}`;
237 | }
238 | 
239 | function showLoading(on) {
240 |   document.getElementById('loading').classList.toggle('hidden', !on);
241 |   if (on) document.getElementById('cards-grid').classList.add('hidden');
242 | }
