/* ── Reset & tokens ─────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:     #0d1117;
  --bg2:    #161b22;
  --bg3:    #21262d;
  --border: #30363d;
  --text:   #e6edf3;
  --muted:  #8b949e;
  --accent: #58a6ff;
  --green:  #3fb950;
  --red:    #f85149;
  --gold:   #d29922;
  --purple: #a371f7;
  --orange: #f0883e;
  --radius: 12px;
  --shadow: 0 4px 24px rgba(0,0,0,.5);
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  line-height: 1.6;
  min-height: 100vh;
}

/* ── Header ── */
header { background: var(--bg2); border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 100; }
.header-inner { max-width: 1300px; margin: 0 auto; padding: 0 24px; height: 60px; display: flex; align-items: center; justify-content: space-between; }
.logo { display: flex; align-items: center; gap: 10px; font-size: 1.2rem; font-weight: 700; }
.logo-icon { font-size: 1.5rem; }
.logo-ai { color: var(--accent); }
.header-meta { display: flex; align-items: center; gap: 16px; }
.timestamp { color: var(--muted); font-size: .85rem; }

/* ── Buttons ── */
.btn { border: none; border-radius: 8px; padding: 7px 16px; font-size: .9rem; font-weight: 600; cursor: pointer; transition: opacity .15s, transform .1s; }
.btn:hover { opacity: .85; }
.btn:active { transform: scale(.97); }
.btn-primary { background: var(--accent); color: #0d1117; }

/* ── Hero ── */
.hero { text-align: center; padding: 56px 24px 32px; background: linear-gradient(180deg, #161b22 0%, #0d1117 100%); }
.hero h1 { font-size: clamp(1.6rem, 4vw, 2.6rem); font-weight: 800; margin-bottom: 10px; }
.hero p  { color: var(--muted); font-size: 1.05rem; }

/* ── Controls bar ── */
.controls-bar { background: var(--bg2); border-bottom: 1px solid var(--border); }
.controls-inner { max-width: 1300px; margin: 0 auto; padding: 14px 24px; display: flex; gap: 24px; flex-wrap: wrap; align-items: flex-end; }
.control-group { display: flex; flex-direction: column; gap: 4px; }
