/* ── Reset & tokens ─────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:     #0d1117;
  --bg2:    #161b22;
  --bg3:    #21262d;
  --border: #30363d;
  --text:   #e6edf3;
  --muted:  #8b949e;
  --accent: #58a6ff;
  --green:  #3fb950;
  --red:    #f85149;
  --gold:   #d29922;
  --purple: #a371f7;
  --orange: #f0883e;
  --radius: 8px;
  --shadow: 0 4px 24px rgba(0,0,0,.5);
  /* shared column widths — used by both table-head and .row */
  --c-rank:   32px;
  --c-spark:  80px;
  --c-ticker: 100px;
  --c-price:  80px;
  --c-chg:    68px;
  --c-score:  58px;
  --c-pe:     52px;
  --c-rsi:    46px;
  --c-eps:    64px;
  --c-margin: 64px;
  --c-cap:    72px;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 13px;
  line-height: 1.4;
  min-height: 100vh;
}

/* ── Toolbar (header + controls in one bar) ── */
header {
  background: var(--bg2);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}
.toolbar {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
  height: 48px;
  display: flex;
  align-items: center;
  gap: 20px;
}
.logo { display: flex; align-items: center; gap: 8px; font-size: 1rem; font-weight: 700; white-space: nowrap; }
.logo-ai { color: var(--accent); }
.toolbar-controls { display: flex; align-items: center; gap: 14px; flex: 1; }
.toolbar-right { display: flex; align-items: center; gap: 12px; margin-left: auto; white-space: nowrap; }

/* Controls */
.control-group { display: flex; align-items: center; gap: 5px; }
.control-group label { font-size: .72rem; color: var(--muted); text-transform: uppercase; letter-spacing: .05em; white-space: nowrap; }
.control-group select {
  background: var(--bg3);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 6px;
  padding: 3px 8px;
  font-size: .8rem;
  cursor: pointer;
  height: 26px;
}

/* Buttons */
.btn { border: none; border-radius: 6px; padding: 4px 12px; font-size: .8rem; font-weight: 600; cursor: pointer; transition: opacity .15s, transform .1s; height: 26px; }
.btn:hover { opacity: .85; }
.btn:active { transform: scale(.97); }
.btn-primary { background: var(--accent); color: #0d1117; }

.timestamp { color: var(--muted); font-size: .75rem; }

/* ── Status banner ── */
.status-banner { max-width: 1400px; margin: 8px auto 0; padding: 7px 20px; border-radius: var(--radius); font-size: .85rem; font-weight: 600; }
.status-banner.error  { background: rgba(248,81,73,.15); border: 1px solid var(--red); color: var(--red); }
.status-banner.hidden { display: none; }

/* ── Container ── */
.container { max-width: 1400px; margin: 0 auto; padding: 10px 20px 32px; }

/* ── Loading ── */
.loading-screen { display: flex; flex-direction: column; align-items: center; gap: 16px; padding: 60px 0; color: var(--muted); }
.spinner { width: 36px; height: 36px; border: 3px solid var(--border); border-top-color: var(--accent); border-radius: 50%; animation: spin .8s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

/* ── Table header row ── */
.table-head {
  display: grid;
  grid-template-columns:
    var(--c-rank) var(--c-spark) var(--c-ticker) var(--c-price)
    var(--c-chg) var(--c-score) var(--c-pe) var(--c-rsi)
    var(--c-eps) var(--c-margin) var(--c-cap);
  align-items: center;
  padding: 0 10px;
  height: 28px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 2px;
  font-size: .68rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: .05em;
}
.col-rank   { text-align: center; }
.col-price, .col-chg, .col-score, .col-pe, .col-rsi, .col-eps, .col-margin, .col-cap { text-align: right; }

/* ── Cards list (one row per stock) ── */
.cards-grid { display: flex; flex-direction: column; gap: 3px; }
.hidden { display: none !important; }

