/* ── Stock card ── */
.card { background: var(--bg2); border: 1px solid var(--border); border-radius: var(--radius); padding: 20px; cursor: pointer; transition: transform .15s, box-shadow .15s, border-color .15s; position: relative; overflow: hidden; }
.card:hover { transform: translateY(-3px); box-shadow: var(--shadow); border-color: var(--accent); }
.rank-badge { position: absolute; top: 14px; right: 14px; background: var(--bg3); border: 1px solid var(--border); border-radius: 20px; padding: 2px 10px; font-size: .78rem; color: var(--muted); font-weight: 600; }
.rank-badge.top3 { background: rgba(212,175,55,.12); border-color: var(--gold); color: var(--gold); }
.card-header { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 14px; }
.ticker-circle { width: 48px; height: 48px; border-radius: 12px; background: var(--bg3); display: flex; align-items: center; justify-content: center; font-size: .85rem; font-weight: 700; color: var(--accent); flex-shrink: 0; letter-spacing: -.02em; }
.card-title h2 { font-size: 1rem; font-weight: 700; }
.card-title .company-name { font-size: .82rem; color: var(--muted); margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 200px; }
.sector-tag { display: inline-block; margin-top: 4px; font-size: .72rem; padding: 1px 8px; border-radius: 10px; background: var(--bg3); color: var(--muted); border: 1px solid var(--border); }
.score-block { display: flex; flex-direction: column; align-items: center; margin-left: auto; }
.score-ring { width: 56px; height: 56px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 1.15rem; font-weight: 800; border: 3px solid; }
.score-ring.high   { border-color: var(--green); color: var(--green); }
.score-ring.medium { border-color: var(--gold);  color: var(--gold); }
.score-ring.low    { border-color: var(--red);   color: var(--red); }
.score-label { font-size: .68rem; color: var(--muted); margin-top: 3px; text-align: center; }
.price-row { display: flex; align-items: baseline; gap: 10px; margin-bottom: 14px; }
.price-main { font-size: 1.5rem; font-weight: 700; }
.change-badge { font-size: .85rem; font-weight: 600; padding: 2px 8px; border-radius: 6px; }
.change-badge.pos { background: rgba(63,185,80,.15); color: var(--green); }
.change-badge.neg { background: rgba(248,81,73,.15); color: var(--red); }
.change-badge.neu { background: var(--bg3); color: var(--muted); }

/* sparkline */
.sparkline-wrap { margin-bottom: 14px; }
.sparkline-wrap canvas { width: 100% !important; height: 56px !important; }

/* 52-week range bar */
.range-bar-wrap { margin-bottom: 14px; }
.range-bar-labels { display: flex; justify-content: space-between; font-size: .72rem; color: var(--muted); margin-bottom: 4px; }
.range-bar-track { height: 6px; border-radius: 3px; background: var(--bg3); position: relative; }
.range-bar-fill { position: absolute; left: 0; top: 0; height: 100%; border-radius: 3px; background: linear-gradient(90deg, var(--accent), var(--green)); transition: width .4s ease; }
.range-bar-dot { position: absolute; top: 50%; transform: translate(-50%, -50%); width: 10px; height: 10px; border-radius: 50%; background: var(--text); border: 2px solid var(--bg2); }

/* metrics grid */
.metrics-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px; margin-bottom: 14px; }
.metric { background: var(--bg3); border-radius: 8px; padding: 8px 10px; display: flex; flex-direction: column; gap: 2px; }
.metric-label { font-size: .68rem; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
.metric-value { font-size: .95rem; font-weight: 700; }

/* rationale */
.rationale { border-top: 1px solid var(--border); padding-top: 12px; }
.rationale-item { font-size: .82rem; color: var(--muted); margin-bottom: 3px; }

/* ── Score bars in modal ── */
.subscore-bar-wrap { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
.subscore-label { width: 90px; font-size: .8rem; color: var(--muted); flex-shrink: 0; }
.subscore-track { flex: 1; height: 8px; border-radius: 4px; background: var(--bg3); overflow: hidden; }
.subscore-fill  { height: 100%; border-radius: 4px; background: var(--accent); }
.subscore-val   { width: 36px; text-align: right; font-size: .8rem; font-weight: 600; }

/* ── Legend ── */
.legend { border-top: 1px solid var(--border); padding-top: 32px; padding-bottom: 48px; }
.legend h3 { margin-bottom: 16px; font-size: 1.05rem; }
.legend-grid { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 20px; }
.legend-item { display: flex; align-items: center; gap: 8px; font-size: .85rem; color: var(--muted); }
.pill { font-size: .72rem; font-weight: 700; padding: 2px 8px; border-radius: 20px; }
.pill-blue   { background: rgba(88,166,255,.15);  color: var(--accent); }
.pill-green  { background: rgba(63,185,80,.15);   color: var(--green); }
.pill-purple { background: rgba(163,113,247,.15); color: var(--purple); }
.pill-orange { background: rgba(240,136,62,.15);  color: var(--orange); }
.pill-red    { background: rgba(248,81,73,.15);   color: var(--red); }
.disclaimer  { font-size: .8rem; color: var(--muted); margin-top: 16px; padding: 12px 16px; background: var(--bg2); border-radius: 8px; border: 1px solid var(--border); }

/* ── Modal ── */
.modal-overlay { position: fixed; inset: 0; background: rgba(0,0,0,.7); z-index: 200; display: flex; align-items: center; justify-content: center; padding: 24px; }
.modal { background: var(--bg2); border: 1px solid var(--border); border-radius: var(--radius); max-width: 560px; width: 100%; max-height: 85vh; overflow-y: auto; padding: 28px; position: relative; box-shadow: var(--shadow); }
.modal-close { position: absolute; top: 14px; right: 14px; background: var(--bg3); border: 1px solid var(--border); color: var(--text); border-radius: 6px; width: 30px; height: 30px; font-size: 1rem; cursor: pointer; display: flex; align-items: center; justify-content: center; }
.modal h2 { font-size: 1.4rem; margin-bottom: 4px; }
.modal .modal-sub { color: var(--muted); font-size: .9rem; margin-bottom: 20px; }
.modal-section { margin-bottom: 20px; }
.modal-section h4 { font-size: .85rem; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); margin-bottom: 10px; }

/* ── Responsive ── */
@media (max-width: 600px) {
  .cards-grid { grid-template-columns: 1fr; }
  .metrics-grid { grid-template-columns: 1fr 1fr; }
  .hero h1 { font-size: 1.4rem; }
}

