  align-items: center;
  padding: 0 10px;
  height: 44px;
  background: var(--bg2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  cursor: pointer;
  transition: background .12s, border-color .12s;
  gap: 0;
}
.card:hover { background: var(--bg3); border-color: var(--accent); }

/* rank */
.row-rank { text-align: center; font-size: .75rem; color: var(--muted); font-weight: 600; }
.row-rank.top3 { color: var(--gold); font-weight: 700; }

/* sparkline cell */
.row-spark { width: var(--c-spark); height: 36px; display: flex; align-items: center; padding: 0 4px; }
.row-spark canvas { display: block; width: 100%; height: 36px; }

