.weight-bar {
  background: var(--bg2);
  border-bottom: 1px solid var(--border);
  padding: 5px 20px;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  max-width: 100%;
  overflow: hidden;
}
.weight-bar-label {
  font-size: .7rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: .05em;
  white-space: nowrap;
}
.weight-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 2px 9px;
  font-size: .72rem;
  white-space: nowrap;
}
