167 | // ── Sparkline (pure canvas, compact 36 px tall) ───────────────────────────
168 | function drawSparkline(s) {
169 |   const canvas = document.getElementById(`spark-${s.ticker}`);
170 |   if (!canvas || !s.sparkline || s.sparkline.length < 2) return;
171 | 
172 |   const dpr = window.devicePixelRatio || 1;
173 |   const w   = canvas.parentElement.clientWidth - 8; // subtract padding
174 |   const h   = 36;
175 |   canvas.width  = w * dpr;
176 |   canvas.height = h * dpr;
177 |   canvas.style.width  = w + 'px';
178 |   canvas.style.height = h + 'px';
179 |   const ctx = canvas.getContext('2d');
180 |   ctx.scale(dpr, dpr);
181 | 
182 |   const prices = s.sparkline;
183 |   const min    = Math.min(...prices);
184 |   const max    = Math.max(...prices);
185 |   const range  = max - min || 1;
186 |   const pad    = 2;
187 |   const xFn    = i => (i / (prices.length - 1)) * (w - pad * 2) + pad;
188 |   const yFn    = v => h - pad - ((v - min) / range) * (h - pad * 2);
189 | 
190 |   const isUp = prices[prices.length - 1] >= prices[0];
191 |   const col  = isUp ? '63,185,80' : '248,81,73';
192 |   const grad = ctx.createLinearGradient(0, 0, 0, h);
193 |   grad.addColorStop(0, `rgba(${col},.25)`);
194 |   grad.addColorStop(1, `rgba(${col},0)`);
195 | 
196 |   // filled area
197 |   ctx.beginPath();
198 |   ctx.moveTo(xFn(0), yFn(prices[0]));
199 |   prices.forEach((p, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(p)); });
200 |   ctx.lineTo(xFn(prices.length - 1), h);
201 |   ctx.lineTo(xFn(0), h);
202 |   ctx.closePath();
203 |   ctx.fillStyle = grad;
204 |   ctx.fill();
205 | 
206 |   // line
207 |   ctx.beginPath();
208 |   ctx.moveTo(xFn(0), yFn(prices[0]));
209 |   prices.forEach((p, i) => { if (i > 0) ctx.lineTo(xFn(i), yFn(p)); });
210 |   ctx.strokeStyle = `rgb(${col})`;
211 |   ctx.lineWidth   = 1.5;
212 |   ctx.lineJoin    = 'round';
213 |   ctx.stroke();
214 | }
